tool_input.new_string:
handleSync() {
  // 后端通知（禅道 bug 6023 备注 2026-11-02）：同步接口更换为
  // POST /building/building/extractBuildingBySurveying，入参 buildingId、projectId
  // （原 POST /building/building/extractBuilding 仅传 buildingId，已停用）
  this.$post('/building/building/extractBuildingBySurveying', {
    buildingId: this.getId(),
    projectId: this.form.projectId
  }).then((res) => {
    if (res.code == 200) {
      this.getDetail()
      this.msgSuccess('同步成功')
    } else {
      this.msgError(res.msg)
    }
  })
},

